using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerCombat : MonoBehaviour
{
    [Header("射击配置")]
    [SerializeField] private GameObject bulletPrefab;

    private PlayerStats _stats;
    private float _lastShootTime = -10f;

    /// <summary>射击事件委托：参数为 (方向, 子弹速度, 攻击力)</summary>
    public event System.Action<Vector2, float, float> OnShoot;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();

        if (bulletPrefab == null)
        {
#if UNITY_EDITOR
            Debug.LogWarning("PlayerCombat: 未指定子弹预制体！");
#endif
        }
        else
        {
            // 预热对象池，避免首帧给卡
            ProjectilePool.Prewarm(bulletPrefab, 10);
        }
    }

    /// <summary>尝试射击，由 PlayerController 通过委托调用</summary>
    public void TryShoot()
    {
        if (bulletPrefab == null || _stats == null)
            return;

        if (Time.time < _lastShootTime + _stats.ShootCooldown)
            return;

        // 获取鼠标世界位置
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;

        Vector2 direction = (mouseWorldPos - transform.position).normalized;

        float bulletSpeed = _stats.BulletSpeed;
        float attackStrength = _stats.AttackStrength;

        // 从对象池获取子弹
        GameObject bullet = ProjectilePool.Get(bulletPrefab, transform.position, Quaternion.identity);
        Projectile proj = bullet.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(direction, bulletSpeed, attackStrength, Projectile.OwnerType.Player, gameObject);
        }
#if UNITY_EDITOR
        else
        {
            Debug.LogWarning("子弹预制体缺少 Projectile 组件！");
        }
#endif

        _lastShootTime = Time.time;

        OnShoot?.Invoke(direction, bulletSpeed, attackStrength);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    private Rigidbody2D _rb;
    private PlayerCombat _combat;
    private PlayerStats _stats;
    private Vector2 _moveInput;

    /// <summary>攻击输入委托，由 PlayerCombat 订阅</summary>
    public event System.Action OnAttackInput;

    /// <summary>输入是否被锁定 (房间切换期间)</summary>
    public bool InputLocked { get; set; }

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _combat = GetComponent<PlayerCombat>();
        _stats = GetComponent<PlayerStats>();

        if (_combat != null)
            OnAttackInput += _combat.TryShoot;

#if UNITY_EDITOR
        if (_rb == null)
            Debug.LogWarning("PlayerController: 未找到 Rigidbody2D 组件！");
        if (_combat == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerCombat 组件！");
        if (_stats == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerStats 组件！");
#endif
    }

    void Start()
    {
        if (_stats == null) return;

        CircleCollider2D circle = GetComponent<CircleCollider2D>();
        if (circle != null)
        {
            _stats.ColliderRadius = circle.radius * Mathf.Max(transform.localScale.x, transform.localScale.y);
        }

        // Start 时 MapManager.Instance 已经初始化 (Awake 时序保证)
        if (MapManager.Instance != null)
        {
            MapManager.Instance.OnRoomSwitchStarted += (f, t) => InputLocked = true;
            MapManager.Instance.OnRoomSwitchCompleted += (t) => InputLocked = false;
        }
    }

    void Update()
    {
        if (_stats != null && _stats.IsDead) return;
        if (InputLocked)
        {
            _moveInput = Vector2.zero;
            return;
        }

        float horizontal = Input.GetAxisRaw("Horizontal");
        float vertical = Input.GetAxisRaw("Vertical");
        _moveInput = new Vector2(horizontal, vertical);
        _moveInput = Vector2.ClampMagnitude(_moveInput, 1f);

        if (Input.GetMouseButton(0))
        {
            OnAttackInput?.Invoke();
        }
    }

    void FixedUpdate()
    {
        if (_rb == null || _stats == null) return;
        if (_stats.IsDead) return;
        if (InputLocked) return;

        // 使用 Rigidbody2D 物理驱动，墙壁碰撞由 Collider2D 处理
        _rb.velocity = _moveInput * _stats.MoveSpeed;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [Tooltip("每分钟射击次数，300 = 每秒5发")]
    [SerializeField] private float shotsPerMinute = 300f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    [Header("进化倾向")]
    [Tooltip("进化倾向：正值=朝向宿主，负值=朝向独特。范围 -100 ~ 100")]
    [SerializeField] private float evolutionTendency = 0f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => 60f / shotsPerMinute;
    public float ShotsPerMinute => shotsPerMinute;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    /// <summary>进化倾向：正值=朝向宿主（金色），负值=朝向独特（紫色）。范围 -100 ~ 100</summary>
    public float EvolutionTendency => evolutionTendency;

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        health -= damage;
        health = Mathf.Max(health, 0);

        // 弹出伤害数字（玩家受伤用红色）
        DamagePopup.Spawn(transform.position, damage, isPlayerDamage: true);

        // 角色受击 → 屏幕振动 + 全屏红闪
        if (CameraShake.Instance != null)
        {
            CameraShake.Instance.Shake(1f);
            CameraShake.Instance.FlashRed();
        }

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- Buff 系统属性读写接口 ----------

    /// <summary>通过属性名字符串获取当前值（供 Buff 系统使用）</summary>
    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"      => maxHealth,
            "MoveSpeed"      => moveSpeed,
            "AttackStrength"  => attackStrength,
            "BulletSpeed"    => bulletSpeed,
            "ShotsPerMinute" => shotsPerMinute,
            "ColliderRadius" => colliderRadius,
            "EvolutionTendency" => evolutionTendency,
            _                => throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'")
        };
    }

    /// <summary>通过属性名字符串设置值，自动触发 OnStatChanged（供 Buff 系统使用）</summary>
    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                maxHealth = Mathf.Max(value, 1f);
                break;
            case "MoveSpeed":
                moveSpeed = Mathf.Max(value, 0f);
                break;
            case "AttackStrength":
                attackStrength = Mathf.Max(value, 0f);
                break;
            case "BulletSpeed":
                bulletSpeed = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinute":
                shotsPerMinute = Mathf.Max(value, 0f);
                break;
            case "ColliderRadius":
                colliderRadius = Mathf.Max(value, 0.01f);
                break;
            case "EvolutionTendency":
                evolutionTendency = Mathf.Clamp(value, -100f, 100f);
                break;
            default:
                throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }

    // ---------- 科技树 / 配置接口 ----------

    /// <summary>应用基础配置值（来自 PlayerConfig SO）</summary>
    public void ApplyBaseStats(PlayerConfig config)
    {
        if (config == null) return;

        maxHealth = config.maxHealth;
        moveSpeed = config.moveSpeed;
        attackStrength = config.attackStrength;
        bulletSpeed = config.bulletSpeed;
        shotsPerMinute = config.shotsPerMinute;
        colliderRadius = config.colliderRadius;
        health = maxHealth; // 重置满血

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    /// <summary>叠加科技树加成（在 ApplyBaseStats 之后调用）</summary>
    public void ApplyBonuses(Dictionary<string, float> bonuses)
    {
        if (bonuses == null || bonuses.Count == 0) return;

        foreach (var kvp in bonuses)
        {
            SetStatValue(kvp.Key, GetStatValue(kvp.Key) + kvp.Value);
        }

        // 加成后恢复满血（生命上限可能增加了）
        if (bonuses.ContainsKey("MaxHealth"))
            health = maxHealth;

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shotsPerMinute = Mathf.Max(shotsPerMinute, 1f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
        evolutionTendency = Mathf.Clamp(evolutionTendency, -100f, 100f);
    }
}

using UnityEngine;

/// Homing bacteriophage projectile — flies toward target, marks on hit.
public class BacteriophageProjectile : MonoBehaviour, IHomingProjectile
{
    /// <summary>Static prefab reference for chain spawning (avoids Unity prefab self-reference issues).</summary>
    public static GameObject S_PhagePrefab;

    [Header("Projectile Visual")]
    [SerializeField] private SpriteRenderer _spriteRenderer;

    private Transform _target;
    private float _speed = 6f;
    private float _totalDamage = 40f;
    private Projectile.OwnerType _ownerType;
    private float _casterAttackStrength;
    private float _damageMultiplier;
    private int _totalTicks = 4;
    private float _tickInterval = 1f;
    private int _chainCount = 3;
    private float _chainRadius = 8f;
    private float _chainProjectileSpeed = 6f;

    [Header("Effect Prefabs")]
    [SerializeField] private GameObject _hitEffectPrefab;
    [SerializeField] private GameObject _markVisualPrefab;

    [Header("Chain Reaction")]
    [Tooltip("噬菌体投射物预制体资产（用于死亡传播，非运行时实例）")]
    [SerializeField] private GameObject _phagePrefabAsset;

    private bool _initialized;

    public void Initialize(Transform target, float speed,
        float casterAttackStrength, float damageMultiplier,
        float totalDamage, Projectile.OwnerType ownerType)
    {
        _target = target;
        _speed = speed;
        _totalDamage = totalDamage;
        _ownerType = ownerType;
        _casterAttackStrength = casterAttackStrength;
        _damageMultiplier = damageMultiplier;
        _initialized = true;

        Destroy(gameObject, 5f);
    }

    void Awake()
    {
        // Cache the prefab reference statically (via the serialized _phagePrefabAsset on the prefab)
        if (S_PhagePrefab == null && _phagePrefabAsset != null)
            S_PhagePrefab = _phagePrefabAsset;
    }

    void Update()
    {
        if (!_initialized) return;

        if (_target != null)
        {
            Vector2 direction = (_target.position - transform.position).normalized;
            transform.Translate(direction * _speed * Time.deltaTime, Space.World);

            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
            transform.rotation = Quaternion.Euler(0, 0, angle);
        }
        else
        {
            transform.Translate(Vector2.right * _speed * Time.deltaTime, Space.World);
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!_initialized) return;

        if (other.CompareTag("Obstacles"))
        {
            DestroySelf();
            return;
        }

        string targetTag = _ownerType == Projectile.OwnerType.Player ? "Enemy" : "Player";
        if (!other.CompareTag(targetTag)) return;

        // Hit the correct target — apply mark
        if (other.transform == _target || _target == null)
        {
            ApplyMark(other.gameObject);
        }

        DestroySelf();
    }

    private void ApplyMark(GameObject enemy)
    {
        if (_phagePrefabAsset == null)
            Debug.LogError("[PhageProjectile] _phagePrefabAsset is NULL — chain will not work!");

        var existing = enemy.GetComponent<PhageMarkComponent>();
        if (existing != null)
        {
            // Refresh: destroy old mark, apply new
            Destroy(existing);
        }

        var mark = enemy.AddComponent<PhageMarkComponent>();
        mark.Initialize(_totalDamage, _totalTicks, _tickInterval,
            _chainCount, _chainRadius, _chainProjectileSpeed,
            _phagePrefabAsset, _ownerType,
            _casterAttackStrength, _damageMultiplier,
            _markVisualPrefab);
    }

    private void DestroySelf()
    {
        if (_hitEffectPrefab != null)
        {
            Instantiate(_hitEffectPrefab, transform.position, Quaternion.identity);
        }

        // Detach trail particles and let them dissipate, then destroy
        var trail = transform.Find("TrailParticles");
        if (trail != null)
        {
            trail.SetParent(null);
            var ps = trail.GetComponent<ParticleSystem>();
            if (ps != null)
            {
                ps.Stop(true, ParticleSystemStopBehavior.StopEmitting);
                Destroy(trail.gameObject, ps.main.startLifetime.constantMax + 1f);
            }
            else
            {
                Destroy(trail.gameObject, 2f);
            }
        }

        Destroy(gameObject);
    }

    private void OnBecameInvisible()
    {
        Destroy(gameObject);
    }
}

